def tambah(root, nilai):
    node_baru = {"nilai": nilai, "kiri": None, "kanan": None}
    if root is None:
        return node_baru
    saat_ini = root
    while True:
        if nilai == saat_ini["nilai"]:
            return root
        sisi = "kiri" if nilai < saat_ini["nilai"] else "kanan"
        if saat_ini[sisi] is None:
            saat_ini[sisi] = node_baru
            return root
        saat_ini = saat_ini[sisi]

