from collections import deque

def dfs(graph, awal):
    if awal not in graph:
        return []
    stack, visited, hasil = [awal], set(), []
    while stack:
        node = stack.pop()
        if node in visited:
            continue
        visited.add(node)
        hasil.append(node)
        for tetangga in reversed(graph[node]):
            if tetangga not in visited:
                stack.append(tetangga)
    return hasil

def komponen(graph):
    terlihat, hasil = set(), []
    for node in graph:
        if node not in terlihat:
            kelompok = dfs(graph, node)
            terlihat.update(kelompok)
            hasil.append(kelompok)
    return hasil

def jalur_bfs(graph, awal, tujuan):
    if awal not in graph or tujuan not in graph:
        return None
    antrean, parent = deque([awal]), {awal: None}
    while antrean:
        node = antrean.popleft()
        if node == tujuan:
            jalur = []
            while node is not None:
                jalur.append(node)
                node = parent[node]
            jalur.reverse()
            return jalur
        for tetangga in graph[node]:
            if tetangga not in parent:
                parent[tetangga] = node
                antrean.append(tetangga)
    return None

