def periksa_kurung(teks):
    pasangan = {")": "(", "]": "[", "}": "{"}
    stack = []
    for posisi, karakter in enumerate(teks, start=1):
        if karakter in "([{":
            stack.append((karakter, posisi))
        elif karakter in pasangan:
            if not stack:
                return False, f"Penutup {karakter} tanpa pembuka pada posisi {posisi}"
            pembuka, awal = stack.pop()
            if pembuka != pasangan[karakter]:
                return False, f"Penutup {karakter} tidak cocok pada posisi {posisi}"
    if stack:
        pembuka, posisi = stack[-1]
        return False, f"Pembuka {pembuka} belum ditutup pada posisi {posisi}"
    return True, "Seimbang"

for teks in ["(a + b) * [c]", "([)]", "(()", ")"]:
    valid, pesan = periksa_kurung(teks)
    print(valid, pesan)

import heapq

def buat_penjadwal():
    return {"heap": [], "urutan": 0, "menunggu": set()}

def tambah_tugas(state, id_tugas, prioritas):
    if not isinstance(id_tugas, str) or not id_tugas.strip():
        raise ValueError("ID wajib berupa teks tidak kosong")
    if type(prioritas) is not int or prioritas <= 0:
        raise ValueError("Prioritas harus integer positif")
    id_tugas = id_tugas.strip()
    if id_tugas in state["menunggu"]:
        return False
    heapq.heappush(state["heap"], (prioritas, state["urutan"], id_tugas))
    state["urutan"] += 1
    state["menunggu"].add(id_tugas)
    return True

def layani(state):
    if not state["heap"]:
        return None
    prioritas, nomor, id_tugas = heapq.heappop(state["heap"])
    state["menunggu"].remove(id_tugas)
    return {"id": id_tugas, "prioritas": prioritas}

state = buat_penjadwal()
for id_tugas, prioritas in [("T1", 2), ("T2", 1), ("T3", 1), ("T2", 1)]:
    print("Diterima:", id_tugas, tambah_tugas(state, id_tugas, prioritas))
while state["heap"]:
    hasil = layani(state)
    print("Layanan:", hasil["id"], hasil["prioritas"])
print("Kosong:", layani(state))
